data/schema/air_defense.schema.json.content:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "air_defense.schema.json",
  "title": "防空单位（数值表 1.1、1.2）",
  "type": "object",
  "required": ["units"],
  "properties": {
    "$schema": { "type": "string" },
    "units": { "type": "array", "items": { "$ref": "#/$defs/unit" } }
  },
  "additionalProperties": false,
  "$defs": {
    "unit": {
      "type": "object",
      "required": ["id", "nameKey", "deployTier", "deployGameSec", "packGameSec", "mobility", "moveSpeedKmh", "fireOnMove", "systemPriceMusd", "weapons"],
      "properties": {
        "id": { "$ref": "common.schema.json#/$defs/id" },
        "nameKey": { "$ref": "common.schema.json#/$defs/locKey" },
        "deployTier": {
          "enum": ["instant", "minutes", "hours_short", "hours", "fixed"],
          "description": "部署档：即时 / 分钟 / 小时（短）/ 小时 / 固定阵地"
        },
        "deployGameSec": {
          "type": ["number", "null"], "minimum": 0,
          "description": "展开时间（游戏秒）；null = 不可移动、开局即在阵地"
        },
        "packGameSec": { "type": ["number", "null"], "minimum": 0, "description": "撤收时间（游戏秒）；null = 不可撤收" },
        "mobility": {
          "enum": ["vehicle", "towed", "portable", "fixed"],
          "description": "车载 / 牵引 / 便携 / 固定"
        },
        "moveSpeedKmh": { "type": ["number", "null"], "minimum": 0, "description": "移动速度；null = 不可移动" },
        "fireOnMove": { "enum": ["yes", "partial", "no"], "description": "行进间射击：✔ / 部分 / ✘" },
        "systemPriceMusd": {
          "type": ["number", "null"], "minimum": 0,
          "description": "系统价格（一个火力单元 / 连）；null = 只有库存，无采购价"
        },
        "stockOnly": { "type": "boolean", "description": "苏制库存装备，不可采购" },
        "fireControlRadar": {
          "type": ["object", "null"],
          "required": ["rangeKm", "lowAltitude", "origin"],
          "properties": {
            "rangeKm": { "$ref": "common.schema.json#/$defs/positive" },
            "lowAltitude": { "enum": ["poor", "medium", "good", "very_good"] },
            "origin": { "enum": ["soviet", "western"] },
            "antennaHeightM": { "type": ["number", "null"], "minimum": 0 }
          },
          "additionalProperties": false
        },
        "selfAcquisitionRangeKm": { "type": ["number", "null"], "exclusiveMinimum": 0 },
        "selfAcquisition": { "type": ["string", "null"], "enum": ["optical", null] },
        "weapons": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/weapon" } },
        "_source": { "$ref": "common.schema.json#/$defs/source" },
        "provisional": { "$ref": "common.schema.json#/$defs/provisional" }
      },
      "additionalProperties": false
    },
    "weapon": {
      "type": "object",
      "required": ["id", "nameKey", "kind", "interceptClass", "rangeKm", "ceilingKm", "shotCostMusd", "ammoSupply", "targets"],
      "properties": {
        "id": { "$ref": "common.schema.json#/$defs/id" },
        "nameKey": { "$ref": "common.schema.json#/$defs/locKey" },
        "kind": { "enum": ["gun", "missile", "rocket", "interceptor_drone"] },
        "interceptClass": {
          "$ref": "common.schema.json#/$defs/id",
          "description": "拦截概率类别，引用 rules/intercept.json 的 classes"
        },
        "rangeKm": { "$ref": "common.schema.json#/$defs/positive" },
        "rangeByTagKm": {
          "type": "object",
          "propertyNames": { "$ref": "common.schema.json#/$defs/targetTag" },
          "additionalProperties": { "$ref": "common.schema.json#/$defs/positive" },
          "description": "对特定目标的射程（如反导射程）；未列出的目标使用 rangeKm"
        },
        "ceilingKm": { "$ref": "common.schema.json#/$defs/positive" },
        "shotCostMusd": {
          "type": ["number", "null"], "minimum": 0,
          "description": "单发 / 单次拦截成本；null = 数值表未给出"
        },
        "magazine": {
          "type": ["integer", "null"], "minimum": 1,
          "description": "每个发射架的弹仓（发 / 架）；null = 弹药充足，不计数"
        },
        "magazineRounds": { "type": "integer", "minimum": 1, "description": "身管武器的备弹（发），每次交战耗弹量由 WS01-009 决定" },
        "launchers": {
          "type": ["integer", "null"], "minimum": 1,
          "description": "每个火力单元的发射架数；null = 由关卡配置"
        },
        "perLevelLimit": { "type": "integer", "minimum": 1, "description": "每关最多可发射的数量" },
        "ammoSupply": {
          "enum": ["ample", "medium", "limited", "scarce", "none"],
          "description": "充足 / 中 / 配额 / 稀缺 / 耗尽不补"
        },
        "targets": {
          "type": "array", "minItems": 1, "uniqueItems": true,
          "items": { "$ref": "common.schema.json#/$defs/targetTag" },
          "description": "可拦截目标"
        },
        "lowEfficiencyTargets": {
          "type": "array", "uniqueItems": true,
          "items": { "$ref": "common.schema.json#/$defs/targetTag" },
          "description": "数值表标注\"低效\"的目标（必须同时出现在 targets 中）。低效已体现在拦截概率矩阵中，此字段供界面提示和 AI 选目标参考"
        },
        "targetsFrom": {
          "type": "array",
          "items": { "$ref": "common.schema.json#/$defs/gatedTag" },
          "description": "从某日期起才可拦截的目标"
        },
        "restrictToEnemies": {
          "type": "array", "uniqueItems": true,
          "items": { "$ref": "common.schema.json#/$defs/id" },
          "description": "只能攻击这些敌方单位（引用 enemies/*.json 的 ID）"
        },
        "barrelCooldown": { "type": "boolean", "description": "持续射击需要换枪管冷却" },
        "reactionGameSec": { "type": ["number", "null"], "minimum": 0 },
        "shotIntervalGameSec": { "type": ["number", "null"], "exclusiveMinimum": 0 },
        "interceptorSpeedKmh": { "type": ["number", "null"], "exclusiveMinimum": 0 },
        "roundsPerBurst": { "type": ["integer", "null"], "minimum": 1 }
      },
      "additionalProperties": false
    }
  }
}

data/schema/common.schema.json.content:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "common.schema.json",
  "title": "公共定义",
  "$defs": {
    "id": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9_]*$",
      "description": "数据 ID：小写字母开头，只含小写字母、数字、下划线"
    },
    "locKey": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9_]*(\\.[a-z0-9_]+)+$",
      "description": "本地化键，指向 loc/*.json"
    },
    "yearMonth": {
      "type": "string",
      "pattern": "^20[0-9]{2}-(0[1-9]|1[0-2])$",
      "description": "YYYY-MM，表示该月起生效"
    },
    "date": {
      "type": "string",
      "pattern": "^20[0-9]{2}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$",
      "description": "YYYY-MM-DD"
    },
    "pointM": {
      "type": "array",
      "prefixItems": [{ "type": "number" }, { "type": "number" }],
      "minItems": 2, "maxItems": 2,
      "description": "地图坐标 [x, y]（米）：原点在地图西南角，x 向东、y 向北"
    },
    "polylineM": {
      "type": "array", "minItems": 2,
      "items": { "$ref": "#/$defs/pointM" },
      "description": "折线（米）"
    },
    "polygonM": {
      "type": "array", "minItems": 3,
      "items": { "$ref": "#/$defs/pointM" },
      "description": "多边形（米），首尾不必重复，顶点按逆时针排列"
    },
    "targetTag": {
      "enum": ["UAV", "JET_UAV", "DECOY", "CM", "SCM", "BM", "HBM", "GB", "HELI", "AC_LOW", "AC_HIGH"],
      "description": "目标标签（数值表第 0 节）"
    },
    "accuracyTier": { "enum": ["A", "B", "C", "D"] },
    "probability": { "type": "number", "minimum": 0, "maximum": 1 },
    "nonNegative": { "type": "number", "minimum": 0 },
    "positive": { "type": "number", "exclusiveMinimum": 0 },
    "levelNumber": { "type": "integer", "minimum": 1, "maximum": 18 },
    "minMax": {
      "type": "object",
      "required": ["min", "max"],
      "properties": {
        "min": { "type": "number" },
        "max": { "type": "number" }
      },
      "additionalProperties": false,
      "description": "随机范围（由 SimRandom 掷骰），仅用于数据约定第 3 节列出的例外"
    },
    "source": {
      "type": "object",
      "additionalProperties": { "type": "string" },
      "description": "数值表原始写法，键为字段名，仅供参考，程序不读取"
    },
    "provisional": {
      "type": "object",
      "minProperties": 1,
      "additionalProperties": { "type": "string" },
      "description": "暂定值：键为字段路径，值为原因。需要人审核"
    },
    "periodValue": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["from", "value"],
        "properties": {
          "from": { "$ref": "#/$defs/yearMonth" },
          "value": { "type": "number" }
        },
        "additionalProperties": false
      },
      "description": "随时期变化的数值，按 from 升序；取不晚于当前日期的最后一项"
    },
    "gatedTag": {
      "type": "object",
      "required": ["tag", "from"],
      "properties": {
        "tag": { "$ref": "#/$defs/targetTag" },
        "from": { "$ref": "#/$defs/yearMonth" }
      },
      "additionalProperties": false
    },
    "firstAvailable": {
      "type": "object",
      "properties": {
        "level": { "$ref": "#/$defs/levelNumber" },
        "fullStrengthLevel": { "$ref": "#/$defs/levelNumber" },
        "optional": { "type": "boolean" },
        "infoSourceOnly": { "type": "boolean" }
      },
      "additionalProperties": false,
      "description": "首次可用关卡（数值表中给出时才填写）"
    }
  }
}

