  "$id": "ew.schema.json",
  "title": "电子战单位（数值表 1.4）",
  "type": "object",
  "required": ["ewUnits"],
  "properties": {
    "$schema": { "type": "string" },
    "ewUnits": { "type": "array", "items": { "$ref": "#/$defs/ewUnit" } }
  },
  "additionalProperties": false,
  "$defs": {
    "ewUnit": {
      "type": "object",
      "required": ["id", "nameKey", "radiusKm", "effect", "effectiveAgainst", "emissionExposure", "deployGameSec", "packGameSec", "priceMusd"],
      "properties": {
        "id": { "$ref": "common.schema.json#/$defs/id" },
        "nameKey": { "$ref": "common.schema.json#/$defs/locKey" },
        "radiusKm": { "$ref": "common.schema.json#/$defs/positive" },
        "effect": {
          "enum": ["nav_jam", "nav_spoof", "link_cut", "link_cut_directional", "self_protection"],
          "description": "导航干扰 / 导航欺骗 / 链路中断 / 定向链路中断 / 本车防护"
        },
        "offsetAddCells": { "type": "number", "minimum": 0, "description": "落点额外偏移（格，仅供界面提示参考）" },
        "accuracyTierDrop": { "type": "integer", "minimum": 0, "description": "精度下降档数" },
        "pullChance": { "$ref": "common.schema.json#/$defs/probability", "description": "把目标拉向诱导点的概率" },
        "aiVisionEffectMult": { "type": "number", "minimum": 0, "description": "对 AI 视觉制导型（2025+）的效果倍率" },
        "linkCutOutcomes": {
          "type": "array", "items": { "enum": ["crash", "hover", "return"] },
          "description": "链路中断后的可能结果：坠落 / 悬停 / 返航。权重由 WS01-015 决定"
        },
        "hitProbMult": { "type": "number", "minimum": 0, "description": "冲向受保护目标的命中概率倍率" },
        "protectsSelfOnly": { "type": "boolean" },
        "equipmentSlot": { "type": "boolean", "description": "装在车辆上的装备槽，不单独占位" },
        "effectiveAgainst": {
          "type": "array", "uniqueItems": true,
          "items": { "$ref": "common.schema.json#/$defs/id" },
          "description": "有效对象（敌方单位 ID）"
        },
        "ineffectiveAgainst": {
          "type": "array", "uniqueItems": true,
          "items": { "$ref": "common.schema.json#/$defs/id" },
          "description": "数值表明确列出的无效对象（敌方单位 ID），供界面提示；未出现在 effectiveAgainst 中的单位一律不受影响"
        },
        "emissionExposure": { "enum": ["high", "medium", "low"], "description": "辐射暴露：高 / 中 / 低" },
        "deployGameSec": { "type": "number", "minimum": 0 },
        "packGameSec": { "type": "number", "minimum": 0 },
        "priceMusd": { "type": "number", "minimum": 0 },
        "firstAvailable": { "$ref": "common.schema.json#/$defs/firstAvailable" },
        "_source": { "$ref": "common.schema.json#/$defs/source" },
        "provisional": { "$ref": "common.schema.json#/$defs/provisional" }
      },
      "additionalProperties": false
    }
  }
}

data/schema/fighter.schema.json.content:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "fighter.schema.json",
  "title": "战斗机性能（数值表 1.1、1.2 战斗机行；外部支援使用）",
  "type": "object",
  "required": ["fighters"],
  "properties": {
    "$schema": { "type": "string" },
    "fighters": { "type": "array", "items": { "$ref": "#/$defs/fighter" } }
  },
  "additionalProperties": false,
  "$defs": {
    "fighter": {
      "type": "object",
      "required": ["id", "nameKey", "ceilingKm", "takeoffGameSec", "rearmGameSec", "patrolSpeedKmh", "priceMusd", "weapons"],
      "properties": {
        "id": { "$ref": "common.schema.json#/$defs/id" },
        "nameKey": { "$ref": "common.schema.json#/$defs/locKey" },
        "ceilingKm": { "$ref": "common.schema.json#/$defs/positive" },
        "takeoffGameSec": { "$ref": "common.schema.json#/$defs/nonNegative" },
        "rearmGameSec": { "$ref": "common.schema.json#/$defs/nonNegative", "description": "返航补给时间" },
        "patrolSpeedKmh": { "$ref": "common.schema.json#/$defs/positive" },
        "fireOnMove": { "const": "yes" },
        "priceMusd": { "$ref": "common.schema.json#/$defs/nonNegative", "description": "每架" },
        "weapons": {
          "type": "array", "minItems": 1,
          "items": {
            "type": "object",
            "required": ["id", "nameKey", "kind", "interceptClass", "rangeKm", "shotCostMusd", "loadout", "targets"],
            "properties": {
              "id": { "$ref": "common.schema.json#/$defs/id" },
              "nameKey": { "$ref": "common.schema.json#/$defs/locKey" },
              "kind": { "enum": ["missile", "rocket"] },
              "interceptClass": { "$ref": "common.schema.json#/$defs/id" },
              "rangeKm": { "$ref": "common.schema.json#/$defs/positive" },
              "shotCostMusd": { "$ref": "common.schema.json#/$defs/nonNegative" },
              "loadout": { "type": "integer", "minimum": 1, "description": "每架次携带数量" },
              "targets": {
                "type": "array", "minItems": 1, "uniqueItems": true,
                "items": { "$ref": "common.schema.json#/$defs/targetTag" }
              },
              "reactionGameSec": { "type": ["number", "null"], "minimum": 0 },
              "shotIntervalGameSec": { "type": ["number", "null"], "exclusiveMinimum": 0 },
              "interceptorSpeedKmh": { "type": ["number", "null"], "exclusiveMinimum": 0 }
            },
            "additionalProperties": false
          }
        },
        "_source": { "$ref": "common.schema.json#/$defs/source" },
        "provisional": { "$ref": "common.schema.json#/$defs/provisional" }
      },
      "additionalProperties": false
    }
  }
}

data/schema/level.schema.json.content:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "level.schema.json",
  "title": "关卡元数据 level.json（WBS 02.A）",
  "type": "object",
  "required": ["$schema", "id", "nameKey", "protagonist", "dateRange", "timeStructure", "fighterMode", "nights", "map", "availableUnits", "commandPointsPerNight", "victory", "defeat"],
  "properties": {
    "$schema": { "type": "string" },
    "id": { "$ref": "common.schema.json#/$defs/id" },
    "number": {
      "oneOf": [{ "$ref": "common.schema.json#/$defs/levelNumber" }, { "type": "null" }],
      "description": "战役关卡编号 1–18；null = 测试 / 非战役关卡"
    },
    "nameKey": { "$ref": "common.schema.json#/$defs/locKey" },
    "briefingKey": { "$ref": "common.schema.json#/$defs/locKey" },
    "protagonist": { "enum": ["A", "B", "AB"], "description": "主角线：A 空军防空 / B 陆军 / 双主角" },
    "dateRange": {
      "type": "object", "required": ["from", "to"],
      "properties": {
        "from": { "$ref": "common.schema.json#/$defs/date" },
        "to": { "$ref": "common.schema.json#/$defs/date" }
      },
      "additionalProperties": false,
      "description": "历史日期范围；决定电子战效能、拦截概率等随时期变化的数值"
    },
    "timeStructure": { "enum": ["A", "B", "C", "D", "E"], "description": "GDD 11.4：A 单场战斗 / B 决定性一夜 / C 关键夜晚组合 / D 持续压力 / E 经营战役" },
    "fighterMode": {
      "enum": ["none", "offmap_auto", "offmap_call", "onmap_airbase", "onmap_support_facility"],
      "description": "GDD 8.9：无 / 场外 AI 自动 / 场外呼叫 / 机场在地图内 / 支撑设施在地图内"
    },
    "fighterSortiesPerNight": { "type": "integer", "minimum": 0, "description": "每夜战斗机额度（rules/support.json 的范围内）" },
    "nights": { "type": "integer", "minimum": 1, "description": "需要亲自指挥的夜晚数" },
    "map": {
      "type": "object",
      "required": ["widthM", "heightM", "heightmap"],
      "properties": {
        "widthM": { "type": "number", "exclusiveMinimum": 0 },
        "heightM": { "type": "number", "exclusiveMinimum": 0 },
        "heightmap": {
          "type": "object",
          "required": ["file", "metersPerPixel", "minElevationM", "maxElevationM"],
          "properties": {
            "file": { "type": "string", "pattern": "^map/[a-z0-9_]+\\.png$", "description": "16 位灰度 PNG，相对关卡目录；像素 (0,0) 为西北角" },
            "metersPerPixel": { "type": "number", "exclusiveMinimum": 0 },
            "minElevationM": { "type": "number", "description": "灰度 0 对应的海拔" },
            "maxElevationM": { "type": "number", "description": "灰度 65535 对应的海拔" }
          },
          "additionalProperties": false
        },
        "attribution": { "type": "array", "items": { "type": "string" }, "description": "地图数据来源与许可署名（OSM 等）" }
      },
      "additionalProperties": false
    },
    "availableUnits": {
      "type": "array", "minItems": 1,
      "items": {
        "type": "object", "required": ["unit", "count"],
        "properties": {
          "unit": { "$ref": "common.schema.json#/$defs/id", "description": "引用 units/*.json 的 ID" },
          "count": { "type": "integer", "minimum": 1 },
          "source": { "enum": ["quota", "city", "stock"], "description": "配额 / 城市资源 / 苏制库存（GDD 9.2）" }
        },
        "additionalProperties": false
      }
    },
    "ammoQuota": {
      "type": "array",
      "items": {
        "type": "object", "required": ["weapon", "count"],
        "properties": {
          "weapon": { "$ref": "common.schema.json#/$defs/id" },
          "count": { "type": "integer", "minimum": 0 }
        },
        "additionalProperties": false
      },
      "description": "开局弹药配额（不写 = 每个发射架按弹仓满载）"
    },
    "launcherOverrides": {
      "type": "array",
      "items": {
        "type": "object", "required": ["unit", "weapon", "launchers"],
        "properties": {
          "unit": { "$ref": "common.schema.json#/$defs/id" },
          "weapon": { "$ref": "common.schema.json#/$defs/id" },
          "launchers": { "type": "integer", "minimum": 1 }
        },
        "additionalProperties": false
      },
      "description": "历史例外覆盖发射架数（如第 9 关敖德萨爱国者 2 具发射架，见 03_engagement_weapons.md §1.5.1）"
    },
    "commandPointsPerNight": { "type": "integer", "minimum": 0 },
    "cityResourcePerDay": { "type": "number", "minimum": 0 },
    "allowManualPause": { "type": "boolean" },
    "endWhenClear": { "type": "boolean" },
    "victory": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/condition" } },
    "defeat": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/condition" } },
    "_source": { "$ref": "common.schema.json#/$defs/source" },
    "provisional": { "$ref": "common.schema.json#/$defs/provisional" }
  },
  "additionalProperties": false,
  "$defs": {
    "condition": {
      "type": "object",
      "required": ["type"],
      "properties": {
        "type": {
          "enum": ["survive_nights", "survive_game_sec", "structure_destroyed", "weighted_damage_at_least", "grid_collapse"],
          "description": "撑过 N 夜 / 撑过 N 游戏秒 / 指定保护目标被毁 / 加权损失达到比例 / 电网崩溃（断电消费者比例 >= fraction，缺省见 rules/civil.json）"
        },
        "nights": { "type": "integer", "minimum": 1 },
        "gameSec": { "type": "number", "exclusiveMinimum": 0 },
        "structure": { "$ref": "common.schema.json#/$defs/id" },
        "fraction": { "$ref": "common.schema.json#/$defs/probability" }
      },
      "additionalProperties": false
    }
  }
}

data/schema/level_content.schema.json.content:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "level_content.schema.json",
  "title": "关卡情报 intel.json 与剧情事件 events.json（WBS 02.A）",
  "type": "object",
  "required": ["$schema", "kind"],
  "properties": {
    "kind": { "enum": ["intel", "events", "level_flow"] }
  },
  "allOf": [
    { "if": { "properties": { "kind": { "const": "intel" } } },      "then": { "$ref": "#/$defs/intel" } },
    { "if": { "properties": { "kind": { "const": "events" } } },     "then": { "$ref": "#/$defs/events" } },
    { "if": { "properties": { "kind": { "const": "level_flow" } } }, "then": { "$ref": "#/$defs/level_flow" } }
  ],
  "$defs": {
    "intel": {
      "type": "object",
      "required": ["nights"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "nights": {
          "type": "array",
          "items": {
            "type": "object", "required": ["night", "items"],
            "properties": {
              "night": { "type": "integer", "minimum": 1 },
              "items": {
                "type": "array",
                "items": {
                  "type": "object", "required": ["textKey", "accurate"],
                  "properties": {
                    "textKey": { "$ref": "common.schema.json#/$defs/locKey" },
                    "accurate": { "type": "boolean", "description": "情报是否准确（可能有误，GDD 5.1）" },
                    "confidence": { "enum": ["confirmed", "probable", "rumor"], "description": "可信度标签（06_client_graybox.md §3.3）" },
                    "relatedWave": { "$ref": "common.schema.json#/$defs/id" }
                  },
                  "additionalProperties": false
                }
              }
            },
            "additionalProperties": false
          }
        }
      },
      "additionalProperties": false
    },
    "events": {
      "type": "object",
      "required": ["events"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "events": {
          "type": "array",
          "items": {
            "type": "object", "required": ["id", "trigger", "actions"],
            "properties": {
              "id": { "$ref": "common.schema.json#/$defs/id" },
              "once": { "type": "boolean", "description": "默认 true：单夜内只触发一次（05_campaign_economy.md §5.2）" },
              "trigger": {
                "type": "object", "required": ["type"],
                "properties": {
                  "type": { "enum": ["night_start", "at_game_sec", "structure_destroyed", "unit_destroyed", "wave_spawned", "exposure_at_least"] },
                  "night": { "type": "integer", "minimum": 1 },
                  "gameSec": { "type": "number", "minimum": 0 },
                  "ref": { "$ref": "common.schema.json#/$defs/id", "description": "相关的保护目标 / 单位 / 波次 ID" },
                  "threshold": { "type": "number", "description": "exposure_at_least 的暴露度阈值" }
                },
                "additionalProperties": false
              },
              "actions": {
                "type": "array", "minItems": 1,
                "items": { "$ref": "#/$defs/eventAction" }
              }
            },
            "additionalProperties": false
          }
        }
      },
      "additionalProperties": false
    },
    "eventAction": {
      "type": "object", "required": ["type"],
      "properties": {
        "type": { "enum": ["dialogue", "spawn_wave", "choice", "set_alert"] },
        "dialogueKey": { "$ref": "common.schema.json#/$defs/locKey" },
        "wave": { "$ref": "common.schema.json#/$defs/id" },
        "choiceKey": { "$ref": "common.schema.json#/$defs/locKey" },
        "timeoutGameSec": { "type": "number", "exclusiveMinimum": 0 },
        "defaultOption": { "type": "integer", "minimum": 0 },
        "optionEffects": {
          "type": "array",
          "items": {
            "type": "object", "required": ["option", "actions"],
            "properties": {
              "option": { "type": "integer", "minimum": 0 },
              "actions": { "type": "array", "items": { "$ref": "#/$defs/eventAction" } }
            },
            "additionalProperties": false
          }
        }
      },
      "additionalProperties": false
    },
    "level_flow": {
      "type": "object",
      "required": ["segments"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "segments": {
          "type": "array", "minItems": 1,
          "items": {
            "type": "object", "required": ["type"],
            "properties": {
              "type": { "enum": ["playable_night", "day", "time_jump", "auto_night", "supply_window"] },
              "night": { "type": "integer", "minimum": 1 },
              "daysSkipped": { "type": "integer", "minimum": 1 },
              "nightsCount": { "type": "integer", "minimum": 1 },
              "templateNight": { "type": "integer", "minimum": 0 },
              "narrativeKey": { "$ref": "common.schema.json#/$defs/locKey" },
              "ammoDelivery": {
                "type": "array",
                "items": {
                  "type": "object", "required": ["weapon", "count"],
                  "properties": {
                    "weapon": { "$ref": "common.schema.json#/$defs/id" },
                    "count": { "type": "integer", "minimum": 0 }
                  },
                  "additionalProperties": false
                }
              }
            },
            "additionalProperties": false
          }
        }
      },
      "additionalProperties": false
    }
  }
}

data/schema/map.schema.json.content:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "map.schema.json",
  "title": "关卡地图数据：layers / structures / grid / deploy（WBS 02.A）",
  "description": "四个地图文件共用本 Schema，用 kind 区分",
  "type": "object",
  "required": ["$schema", "kind"],
  "properties": {
    "kind": { "enum": ["layers", "structures", "grid", "deploy"] }
  },
  "allOf": [
    { "if": { "properties": { "kind": { "const": "layers" } } },     "then": { "$ref": "#/$defs/layers" } },
    { "if": { "properties": { "kind": { "const": "structures" } } }, "then": { "$ref": "#/$defs/structures" } },
    { "if": { "properties": { "kind": { "const": "grid" } } },       "then": { "$ref": "#/$defs/grid" } },
    { "if": { "properties": { "kind": { "const": "deploy" } } },     "then": { "$ref": "#/$defs/deploy" } }
  ],
  "$defs": {
    "layers": {
      "type": "object",
      "required": ["rivers", "roads", "bridges", "urban", "forests", "borders", "restrictedZones"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "rivers": {
          "type": "array",
          "items": {
            "type": "object", "required": ["id", "pathM", "widthM"],
            "properties": {
              "id": { "$ref": "common.schema.json#/$defs/id" },
              "nameKey": { "$ref": "common.schema.json#/$defs/locKey" },
              "pathM": { "$ref": "common.schema.json#/$defs/polylineM" },
              "widthM": { "type": "number", "exclusiveMinimum": 0 }
            },
            "additionalProperties": false
          }
        },
        "roads": {
          "type": "array",
          "items": {
            "type": "object", "required": ["id", "pathM", "class"],
            "properties": {
              "id": { "$ref": "common.schema.json#/$defs/id" },
              "pathM": { "$ref": "common.schema.json#/$defs/polylineM" },
              "class": { "enum": ["highway", "main", "local"] }
            },
            "additionalProperties": false
          }
        },
        "bridges": {
          "type": "array",
          "items": {
            "type": "object", "required": ["id", "pathM"],
            "properties": {
              "id": { "$ref": "common.schema.json#/$defs/id" },
              "pathM": { "$ref": "common.schema.json#/$defs/polylineM" },
              "road": { "$ref": "common.schema.json#/$defs/id" },
              "destructible": { "type": "boolean", "description": "可被炸毁（如第 2 关的炸桥技能）" }
            },
            "additionalProperties": false
          }
        },
        "urban": {
          "type": "array",
          "items": {
            "type": "object", "required": ["id", "polygonM", "density"],
            "properties": {
              "id": { "$ref": "common.schema.json#/$defs/id" },
              "polygonM": { "$ref": "common.schema.json#/$defs/polygonM" },
              "density": { "enum": ["core", "dense", "suburban"], "description": "城区密度；城区上空拦截产生碎片（数值表 3.6）" }
            },
            "additionalProperties": false
          }
        },
        "forests": {
          "type": "array",
          "items": {
            "type": "object", "required": ["id", "polygonM"],
            "properties": {
              "id": { "$ref": "common.schema.json#/$defs/id" },
              "polygonM": { "$ref": "common.schema.json#/$defs/polygonM" }
            },
            "additionalProperties": false
          }
        },
        "borders": {
          "type": "array",
          "items": {
            "type": "object", "required": ["id", "pathM", "kind"],
            "properties": {
              "id": { "$ref": "common.schema.json#/$defs/id" },
              "pathM": { "$ref": "common.schema.json#/$defs/polylineM" },
              "kind": { "enum": ["oblast", "national", "frontline"] }
            },
            "additionalProperties": false
          }
        },
        "restrictedZones": {
          "type": "array",
          "items": {
            "type": "object", "required": ["id", "polygonM", "rule"],
            "properties": {
              "id": { "$ref": "common.schema.json#/$defs/id" },
              "polygonM": { "$ref": "common.schema.json#/$defs/polygonM" },
              "rule": { "enum": ["no_engagement", "restricted_engagement", "frontline_risk"], "description": "禁止交战 / 限制交战 / 前线风险区（不可呼叫战斗机）（GDD 8.9、8.10）" },
              "reason": { "enum": ["border", "nuclear_plant", "civil_corridor", "frontline"] }
            },
            "additionalProperties": false
          }
        }
      },
      "additionalProperties": false
    },

    "structures": {
      "type": "object",
      "required": ["structures"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "structures": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["id", "nameKey", "type", "positionM", "radiusM", "weight", "hp"],
            "properties": {
              "id": { "$ref": "common.schema.json#/$defs/id" },
              "nameKey": { "$ref": "common.schema.json#/$defs/locKey" },
              "type": {
                "enum": ["power_plant", "substation", "command_post", "factory", "residential", "port", "shipyard", "water_plant", "hospital", "shelter", "airbase_runway", "airbase_hangar", "repair_plant", "bridge"],
                "description": "保护目标类型；生产设施一律虚构（GDD 17）"
              },
              "positionM": { "$ref": "common.schema.json#/$defs/pointM" },
              "radiusM": { "type": "number", "exclusiveMinimum": 0, "description": "占地半径，用于命中判定" },
              "weight": { "type": "number", "minimum": 0, "description": "保护权重（上级下达，GDD 8.5）" },
              "hp": { "type": "integer", "minimum": 1 },
              "gridNode": { "$ref": "common.schema.json#/$defs/id", "description": "所属电网节点（引用 grid.json）" }
            },
            "additionalProperties": false
          }
        }
      },
      "additionalProperties": false
    },

    "grid": {
      "type": "object",
      "required": ["nodes", "links"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "nodes": {
          "type": "array",
          "items": {
            "type": "object", "required": ["id", "type", "positionM"],
            "properties": {
              "id": { "$ref": "common.schema.json#/$defs/id" },
              "type": { "enum": ["source", "substation", "consumer"], "description": "电源 / 变电站 / 用户" },
              "positionM": { "$ref": "common.schema.json#/$defs/pointM" },
              "offMapSupply": { "type": "boolean", "description": "地图外的上游电源（外部电网）" }
            },
            "additionalProperties": false
          }
        },
        "links": {
          "type": "array",
          "items": {
            "type": "object", "required": ["from", "to"],
            "properties": {
              "from": { "$ref": "common.schema.json#/$defs/id", "description": "连接端点 A（建议书写方向：上游 → 下游）" },
              "to": { "$ref": "common.schema.json#/$defs/id", "description": "连接端点 B" }
            },
            "additionalProperties": false
          },
          "description": "电网连线（模拟中按无向图计算连通性，见 04_ew_deception_damage.md §6.3）：节点只要有一条经工作节点通向工作电源（source）的路径就有电"
        }
      },
      "additionalProperties": false
    },

    "deploy": {
      "type": "object",
      "required": ["zones", "forbidden", "alternatePositions"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "zones": {
          "type": "array", "minItems": 1,
          "items": {
            "type": "object", "required": ["id", "polygonM"],
            "properties": {
              "id": { "$ref": "common.schema.json#/$defs/id" },
              "polygonM": { "$ref": "common.schema.json#/$defs/polygonM" },
              "allowedMobility": {
                "type": "array", "items": { "enum": ["vehicle", "towed", "portable", "fixed"] },
                "description": "允许部署的机动类型；不写 = 全部允许"
              }
            },
            "additionalProperties": false
          }
        },
        "forbidden": {
          "type": "array",
          "items": {
            "type": "object", "required": ["id", "polygonM", "reason"],
            "properties": {
              "id": { "$ref": "common.schema.json#/$defs/id" },
              "polygonM": { "$ref": "common.schema.json#/$defs/polygonM" },
              "reason": { "enum": ["water", "urban_core", "frontline", "other"] }
            },
            "additionalProperties": false
          }
        },
        "alternatePositions": {
          "type": "array",
          "items": {
            "type": "object", "required": ["id", "positionM", "surveyed"],
            "properties": {
              "id": { "$ref": "common.schema.json#/$defs/id" },
              "positionM": { "$ref": "common.schema.json#/$defs/pointM" },
              "surveyed": { "type": "boolean", "description": "预先勘察的备用阵地（rules/positions.json）" }
            },
            "additionalProperties": false
          }
        }
      },
      "additionalProperties": false
    }
  }
}

data/schema/rules.schema.json.content:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "rules.schema.json",
  "title": "规则参数（数值表第 0、3、4 节及 1.3–1.6 节的规则部分）",
  "description": "每个 rules/*.json 用 kind 字段声明自己的类型，按 kind 套用对应定义",
  "type": "object",
  "required": ["kind"],
  "properties": {
    "kind": { "enum": ["conventions", "accuracy", "damage", "intercept", "exposure", "emission", "debris", "tracks", "ew", "positions", "support", "economy", "movement", "terrain", "engagement", "civil", "enemy_ai", "commands", "campaign_rules"] }
  },
  "allOf": [
    { "if": { "properties": { "kind": { "const": "conventions" } } },    "then": { "$ref": "#/$defs/conventions" } },
    { "if": { "properties": { "kind": { "const": "accuracy" } } },       "then": { "$ref": "#/$defs/accuracy" } },
    { "if": { "properties": { "kind": { "const": "damage" } } },         "then": { "$ref": "#/$defs/damage" } },
    { "if": { "properties": { "kind": { "const": "intercept" } } },      "then": { "$ref": "#/$defs/intercept" } },
    { "if": { "properties": { "kind": { "const": "exposure" } } },       "then": { "$ref": "#/$defs/exposure" } },
    { "if": { "properties": { "kind": { "const": "emission" } } },       "then": { "$ref": "#/$defs/emission" } },
    { "if": { "properties": { "kind": { "const": "debris" } } },         "then": { "$ref": "#/$defs/debris" } },
    { "if": { "properties": { "kind": { "const": "tracks" } } },         "then": { "$ref": "#/$defs/tracks" } },
    { "if": { "properties": { "kind": { "const": "ew" } } },             "then": { "$ref": "#/$defs/ew" } },
    { "if": { "properties": { "kind": { "const": "positions" } } },      "then": { "$ref": "#/$defs/positions" } },
    { "if": { "properties": { "kind": { "const": "support" } } },        "then": { "$ref": "#/$defs/support" } },
    { "if": { "properties": { "kind": { "const": "economy" } } },        "then": { "$ref": "#/$defs/economy" } },
    { "if": { "properties": { "kind": { "const": "movement" } } },       "then": { "$ref": "#/$defs/movement" } },
    { "if": { "properties": { "kind": { "const": "terrain" } } },        "then": { "$ref": "#/$defs/terrain" } },
    { "if": { "properties": { "kind": { "const": "engagement" } } },     "then": { "$ref": "#/$defs/engagement" } },
    { "if": { "properties": { "kind": { "const": "civil" } } },          "then": { "$ref": "#/$defs/civil" } },
    { "if": { "properties": { "kind": { "const": "enemy_ai" } } },       "then": { "$ref": "#/$defs/enemy_ai" } },
    { "if": { "properties": { "kind": { "const": "commands" } } },       "then": { "$ref": "#/$defs/commands" } },
    { "if": { "properties": { "kind": { "const": "campaign_rules" } } }, "then": { "$ref": "#/$defs/campaign_rules" } }
  ],
  "$defs": {
    "prob": { "$ref": "common.schema.json#/$defs/probability" },
    "mult": { "type": "number", "minimum": 0 },

    "conventions": {
      "type": "object",
      "required": ["gameSecToWorldSec", "worldStepSec", "cellKm", "machKmh", "currency"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "gameSecToWorldSec": { "type": "number", "exclusiveMinimum": 0 },
        "worldStepSec": { "type": "number", "exclusiveMinimum": 0 },
        "cellKm": { "type": "number", "exclusiveMinimum": 0 },
        "machKmh": { "type": "number", "exclusiveMinimum": 0 },
        "currency": { "const": "Musd" }
      },
      "additionalProperties": false
    },

    "accuracy": {
      "type": "object",
      "required": ["tierOrder", "tiers", "spotterTierBoost"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "tierOrder": { "type": "array", "items": { "$ref": "common.schema.json#/$defs/accuracyTier" }, "minItems": 4, "maxItems": 4, "uniqueItems": true, "description": "从差到好" },
        "tiers": {
          "type": "object",
          "required": ["A", "B", "C", "D"],
          "additionalProperties": {
            "type": "object",
            "required": ["offsetCells", "ewExtraCells"],
            "properties": {
              "offsetCells": { "$ref": "common.schema.json#/$defs/minMax" },
              "ewExtraCells": { "type": "number", "minimum": 0 }
            },
            "additionalProperties": false
          }
        },
        "spotterTierBoost": { "type": "integer", "minimum": 0 }
      },
      "additionalProperties": false
    },

    "damage": {
      "type": "object",
      "required": ["bands", "splashFalloff", "unitFootprintCells", "componentRadarChance"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "bands": {
          "type": "array", "minItems": 1,
          "items": {
            "type": "object",
            "required": ["minLevel", "maxLevel", "airDefense", "civilBuildings", "gridDamagePct"],
            "properties": {
              "minLevel": { "type": "integer", "minimum": 0, "maximum": 10 },
              "maxLevel": { "type": "integer", "minimum": 0, "maximum": 10 },
              "airDefense": {
                "type": "object",
                "required": ["effect"],
                "properties": {
                  "effect": { "enum": ["light_damage", "heavy_damage", "destroy_component", "destroy_fire_unit", "destroy_fire_unit_and_adjacent"] },
                  "efficiencyMult": { "$ref": "#/$defs/mult" },
                  "repairable": { "type": "boolean" },
                  "suspendGameSec": { "type": "number", "minimum": 0 }
                },
                "additionalProperties": false
              },
              "civilBuildings": {
                "type": "object",
                "required": ["effect"],
                "properties": {
                  "effect": { "enum": ["minor", "buildings", "block"] },
                  "destroyed": { "$ref": "common.schema.json#/$defs/minMax" }
                },
                "additionalProperties": false
              },
              "gridDamagePct": { "type": "number", "minimum": 0, "maximum": 100 }
            },
            "additionalProperties": false
          }
        },
        "splashFalloff": {
          "type": "object",
          "required": ["center", "edge", "curve"],
          "properties": {
            "center": { "$ref": "#/$defs/mult" },
            "edge": { "$ref": "#/$defs/mult" },
            "curve": { "const": "linear" }
          },
          "additionalProperties": false
        },
        "unitFootprintCells": { "type": "number", "exclusiveMinimum": 0 },
        "componentRadarChance": { "$ref": "#/$defs/prob" }
      },
      "additionalProperties": false
    },

    "intercept": {
      "type": "object",
      "required": ["decoyUsesColumn", "classes", "modifiers"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "decoyUsesColumn": { "$ref": "common.schema.json#/$defs/targetTag" },
        "classes": {
          "type": "object",
          "propertyNames": { "$ref": "common.schema.json#/$defs/id" },
          "additionalProperties": {
            "type": "object",
            "propertyNames": { "$ref": "common.schema.json#/$defs/targetTag" },
            "additionalProperties": {
              "oneOf": [
                { "$ref": "#/$defs/prob" },
                {
                  "type": "array", "minItems": 1,
                  "items": {
                    "type": "object", "required": ["from", "value"],
                    "properties": { "from": { "$ref": "common.schema.json#/$defs/yearMonth" }, "value": { "$ref": "#/$defs/prob" } },
                    "additionalProperties": false
                  }
                }
              ]
            }
          },
          "description": "拦截概率类别 → 目标标签 → 单发基础概率（或随时期变化的数组）。缺失 = 该类别不能拦截该目标"
        },
        "modifiers": {
          "type": "object",
          "required": ["trackVague", "trackApproximateCued", "noCueSelfSearch", "newPositionFirstNight", "crewFatigue", "aceCrew", "restrictedEngagement", "interceptorDroneInFriendlyEw", "evasiveTargetVsInterceptorDrone"],
          "additionalProperties": {
            "type": "object",
            "properties": {
              "probMult": { "$ref": "#/$defs/mult" },
              "gunProbMult": { "$ref": "#/$defs/mult" },
              "missilesAllowed": { "type": "boolean" },
              "firstShotReactionTimeMult": { "$ref": "#/$defs/mult" },
              "reactionTimeMult": { "$ref": "#/$defs/mult" },
              "minConsecutiveNights": { "type": "integer", "minimum": 1 },
              "from": { "$ref": "common.schema.json#/$defs/yearMonth" },
              "enemies": { "type": "array", "items": { "$ref": "common.schema.json#/$defs/id" } }
            },
            "additionalProperties": false
          }
        }
      },
      "additionalProperties": false
    },

    "exposure": {
      "type": "object",
      "required": ["min", "max", "ratesPerGameSec", "perMissileLaunched", "enemyReconRadiusKm", "onRelocate", "sensorExposureLevelRatesPerGameSec", "ewExposureLevelRatesPerGameSec", "thresholds"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "min": { "type": "number" },
        "max": { "type": "number" },
        "ratesPerGameSec": {
          "type": "object",
          "required": ["fireControlSelfSearch", "fireControlCued", "silent", "enemyReconNearby"],
          "additionalProperties": { "type": "number" }
        },
        "perMissileLaunched": { "type": "number", "minimum": 0 },
        "enemyReconRadiusKm": { "type": "number", "exclusiveMinimum": 0 },
        "onRelocate": {
          "type": "object",
          "required": ["resetTo", "toScoutedPositionMult"],
          "properties": { "resetTo": { "type": "number" }, "toScoutedPositionMult": { "$ref": "#/$defs/mult" } },
          "additionalProperties": false
        },
        "sensorExposureLevelRatesPerGameSec": {
          "type": "object", "required": ["high", "medium", "zero", "none"],
          "additionalProperties": { "type": "number", "minimum": 0 }
        },
        "ewExposureLevelRatesPerGameSec": {
          "type": "object", "required": ["high", "medium", "low"],
          "additionalProperties": { "type": "number", "minimum": 0 }
        },
        "thresholds": {
          "type": "array",
          "items": {
            "type": "object", "required": ["atLeast", "consequence"],
            "properties": {
              "atLeast": { "type": "number" },
              "consequence": { "enum": ["anti_radiation_priority_tonight", "known_target_list_next_night", "precision_strike_tonight"] }
            },
            "additionalProperties": false
          }
        }
      },
      "additionalProperties": false
    },

    "emission": {
      "type": "object",
      "required": ["defaultStrategy", "dutyCycleDefaultOnGameSec", "dutyCycleDefaultOffGameSec", "decoyLeadGameSec", "defaultReferenceRangeKm", "strategies", "triggers", "shutdownTiming"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "defaultStrategy": { "$ref": "common.schema.json#/$defs/id" },
        "dutyCycleDefaultOnGameSec": { "type": "number", "exclusiveMinimum": 0 },
        "dutyCycleDefaultOffGameSec": { "type": "number", "exclusiveMinimum": 0 },
        "decoyLeadGameSec": { "type": "number", "exclusiveMinimum": 0 },
        "defaultReferenceRangeKm": { "type": "number", "exclusiveMinimum": 0 },
        "strategies": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["id", "nameKey", "activation", "exposureMult", "reactionTimeMult"],
            "properties": {
              "id": { "$ref": "common.schema.json#/$defs/id" },
              "nameKey": { "$ref": "common.schema.json#/$defs/locKey" },
              "activation": { "enum": ["always", "approximate_warning", "duty_cycle", "last_moment", "after_decoy"] },
              "exposureMult": { "$ref": "#/$defs/mult" },
              "reactionTimeMult": { "$ref": "#/$defs/mult" },
              "trackInterrupted": { "type": "boolean" },
              "configurableOnOff": { "type": "boolean" },
              "canRelocate": { "type": "boolean" },
              "requires": { "type": "array", "items": { "enum": ["approximate_track", "network", "decoy"] } },
              "availableFromLevel": { "$ref": "common.schema.json#/$defs/levelNumber" },
              "westernSystemsOnly": { "type": "boolean" }
            },
            "additionalProperties": false
          }
        },
        "triggers": {
          "type": "object",
          "required": ["onAntiRadiationIncoming", "afterFiring", "onMainRadarDestroyed"],
          "additionalProperties": { "type": "array", "items": { "type": "string" }, "minItems": 1 }
        },
        "shutdownTiming": {
          "type": "array",
          "items": {
            "type": "object", "required": ["armDistanceFractionAbove", "armHitProbMult"],
            "properties": {
              "armDistanceFractionAbove": { "type": "number", "minimum": 0, "maximum": 1 },
              "armHitProbMult": { "$ref": "#/$defs/mult" }
            },
            "additionalProperties": false
          }
        }
      },
      "additionalProperties": false
    },

    "debris": {
      "type": "object",
      "required": ["urbanInterceptDamageFraction", "urbanInterceptRadiusCells", "ruralInterceptDamageFraction", "divertedImpactFullDamageInUrban", "scoreUrbanInterceptRatio"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "urbanInterceptDamageFraction": { "$ref": "#/$defs/prob" },
        "urbanInterceptRadiusCells": { "type": "number", "minimum": 0 },
        "ruralInterceptDamageFraction": { "$ref": "#/$defs/prob" },
        "divertedImpactFullDamageInUrban": { "type": "boolean" },
        "scoreUrbanInterceptRatio": { "type": "boolean" }
      },
      "additionalProperties": false
    },

    "trackQualityId": { "enum": ["vague", "approximate", "precise"] },
    "tracks": {
      "type": "object",
      "required": ["qualities", "approximateFromLocalSensorCount", "cueing", "warningRadarEnemyAiWeightAs", "bLine", "detectionRules"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "qualities": {
          "type": "array", "minItems": 3, "maxItems": 3,
          "items": {
            "type": "object",
            "required": ["id", "decoyDiscrimination", "missilesAllowed", "display", "actions"],
            "properties": {
              "id": { "$ref": "#/$defs/trackQualityId" },
              "decoyDiscrimination": { "$ref": "#/$defs/prob" },
              "missilesAllowed": { "type": "boolean" },
              "display": { "enum": ["area_and_arrow", "icon_and_error_circle", "precise_icon"] },
              "actions": { "type": "array", "uniqueItems": true, "items": { "enum": ["pre_position", "raise_alert", "vector_fighters", "vector_fire_teams", "vector_interceptor_drones", "cue_fire_control", "launch_missile"] } }
            },
            "additionalProperties": false
          }
        },
        "approximateFromLocalSensorCount": { "type": "integer", "minimum": 1 },
        "cueing": {
          "type": "object",
          "required": ["cued", "uncued"],
          "properties": {
            "cued": {
              "type": "object", "required": ["minTrackQuality", "fireControlOnlyLastReactionTime", "exposureMult"],
              "properties": {
                "minTrackQuality": { "$ref": "#/$defs/trackQualityId" },
                "fireControlOnlyLastReactionTime": { "type": "boolean" },
                "exposureMult": { "$ref": "#/$defs/mult" }
              },
              "additionalProperties": false
            },
            "uncued": {
              "type": "object", "required": ["exposureMult", "firstShotReactionTimeMult"],
              "properties": {
                "exposureMult": { "$ref": "#/$defs/mult" },
                "firstShotReactionTimeMult": { "$ref": "#/$defs/mult" }
              },
              "additionalProperties": false
            }
          },
          "additionalProperties": false
        },
        "warningRadarEnemyAiWeightAs": { "type": "string" },
        "bLine": {
          "type": "object", "required": ["regionalRadarDirectControl", "relayDelayGameSec", "maxTrackQuality"],
          "properties": {
            "regionalRadarDirectControl": { "type": "boolean" },
            "relayDelayGameSec": { "type": "number", "minimum": 0 },
            "maxTrackQuality": { "$ref": "#/$defs/trackQualityId" }
          },
          "additionalProperties": false
        },
        "detectionRules": {
          "type": "object",
          "required": ["lowAltitudeBelowM", "lowAltitudeRangeMult", "largeBlindZoneLowAltitudeRangeMult", "coverageLowAltitudeMinCapability", "closeRangeFraction", "errorRadiusM", "fastUpdateErrorRadiusMult", "trackLostGameSec", "falseAlarmsPerGameSec", "reportDelayGameSec", "opticalWeatherRangeMult", "opticalNightRangeMult", "opticalSearchlightRangeMult", "unpoweredActiveRangeMult", "winterActiveRangeMult"],
          "properties": {
            "lowAltitudeBelowM": { "type": "number", "minimum": 0 },
            "lowAltitudeRangeMult": { "type": "object", "additionalProperties": { "$ref": "#/$defs/mult" } },
            "largeBlindZoneLowAltitudeRangeMult": { "$ref": "#/$defs/mult" },
            "coverageLowAltitudeMinCapability": { "type": "string" },
            "closeRangeFraction": { "$ref": "#/$defs/prob" },
            "errorRadiusM": { "type": "object", "additionalProperties": { "type": "number", "minimum": 0 } },
            "fastUpdateErrorRadiusMult": { "$ref": "#/$defs/mult" },
            "trackLostGameSec": { "type": "number", "minimum": 0 },
            "falseAlarmsPerGameSec": { "type": "object", "additionalProperties": { "type": "number", "minimum": 0 } },
            "reportDelayGameSec": { "type": "number", "minimum": 0 },
            "opticalWeatherRangeMult": { "type": "object", "additionalProperties": { "$ref": "#/$defs/mult" } },
            "opticalNightRangeMult": { "$ref": "#/$defs/mult" },
            "opticalSearchlightRangeMult": { "$ref": "#/$defs/mult" },
            "unpoweredActiveRangeMult": { "$ref": "#/$defs/mult" },
            "winterActiveRangeMult": { "$ref": "#/$defs/mult" }
          },
          "additionalProperties": false
        }
      },
      "additionalProperties": false
    },

    "ew": {
      "type": "object",
      "required": ["effectivenessByPeriod", "sideEffects", "linkCutOutcomeWeights", "hoverBeforeCrashGameSec", "belowFullStrengthMult", "unpoweredEffectMult", "winterEffectMult", "urbanNavJamMinGameSec"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "effectivenessByPeriod": {
          "type": "array", "minItems": 1,
          "items": {
            "type": "object", "required": ["from", "nav", "counterUas"],
            "properties": {
              "from": { "$ref": "common.schema.json#/$defs/yearMonth" },
              "nav": { "$ref": "#/$defs/prob" },
              "counterUas": { "$ref": "#/$defs/prob" },
              "navTerminalIneffectiveVsAiVision": { "type": "boolean" }
            },
            "additionalProperties": false
          }
        },
        "sideEffects": {
          "type": "object", "required": ["ownDroneLinkCut", "urbanNavJamCityResiliencePerNight"],
          "properties": {
            "ownDroneLinkCut": { "type": "boolean" },
            "urbanNavJamCityResiliencePerNight": { "type": "number" }
          },
          "additionalProperties": false
        },
        "linkCutOutcomeWeights": {
          "type": "object", "required": ["crash", "hover", "return"],
          "properties": {
            "crash": { "$ref": "#/$defs/prob" },
            "hover": { "$ref": "#/$defs/prob" },
            "return": { "$ref": "#/$defs/prob" }
          },
          "additionalProperties": false
        },
        "hoverBeforeCrashGameSec": { "type": "number", "minimum": 0 },
        "belowFullStrengthMult": { "$ref": "#/$defs/mult" },
        "unpoweredEffectMult": { "$ref": "#/$defs/mult" },
        "winterEffectMult": { "$ref": "#/$defs/mult" },
        "urbanNavJamMinGameSec": { "type": "number", "minimum": 0 }
      },
      "additionalProperties": false
    },

    "positions": {
      "type": "object",
      "required": ["preparedAlternate", "newUnsurveyed", "deception"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "preparedAlternate": {
          "type": "object", "required": ["deployTimeMult", "firstNightPenalty", "cost", "persistsForLevel", "availableFromLevel"],
          "properties": {
            "deployTimeMult": { "$ref": "#/$defs/mult" },
            "firstNightPenalty": { "type": "boolean" },
            "cost": { "const": "time_slot" },
            "persistsForLevel": { "type": "boolean" },
            "availableFromLevel": { "$ref": "common.schema.json#/$defs/levelNumber" }
          },
          "additionalProperties": false
        },
        "newUnsurveyed": {
          "type": "object", "required": ["firstNightEfficiencyMult"],
          "properties": { "firstNightEfficiencyMult": { "$ref": "#/$defs/mult" } },
          "additionalProperties": false
        },
        "deception": {
          "type": "object",
          "required": ["fakeLauncherSeeThroughChance", "decoyEmitterExposureLevel"],
          "properties": {
            "fakeLauncherSeeThroughChance": {
              "type": "object", "required": ["low", "medium", "high"],
              "additionalProperties": { "$ref": "#/$defs/prob" }
            },
            "decoyEmitterExposureLevel": { "enum": ["high", "medium", "zero", "none"] }
          },
          "additionalProperties": false
        }
      },
      "additionalProperties": false
    },

    "support": {
      "type": "object",
      "required": ["fighterSortiesPerNight", "bigRaidRefusalChance", "frontlineRiskZoneBlocksCalls", "airspace"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "fighterSortiesPerNight": { "$ref": "common.schema.json#/$defs/minMax" },
        "bigRaidRefusalChance": { "$ref": "#/$defs/prob" },
        "frontlineRiskZoneBlocksCalls": { "type": "boolean" },
        "airspace": {
          "type": "object", "required": ["restrictedEngagement", "fighterExclusiveZone"],
          "properties": {
            "restrictedEngagement": {
              "type": "object", "required": ["isDefault", "confirmedHostileOnly", "reactionTimeMult"],
              "properties": { "isDefault": { "type": "boolean" }, "confirmedHostileOnly": { "type": "boolean" }, "reactionTimeMult": { "$ref": "#/$defs/mult" } },
              "additionalProperties": false
            },
            "fighterExclusiveZone": {
              "type": "object", "required": ["isDefault", "groundHoldFire"],
              "properties": { "isDefault": { "type": "boolean" }, "groundHoldFire": { "type": "boolean" } },
              "additionalProperties": false
            }
          },
          "additionalProperties": false
        }
      },
      "additionalProperties": false
    },

    "economy": {
      "type": "object",
      "required": ["exchangeRatio", "ammoTiers", "historicalEvents", "commandPointsPerNight", "trust", "crossLevelModClamp", "cityResource", "supply", "repair", "relocation", "emergencySupport", "requests"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "exchangeRatio": {
          "type": "object", "required": ["numerator", "denominator"],
          "properties": { "numerator": { "type": "string" }, "denominator": { "type": "string" } },
          "additionalProperties": false
        },
        "ammoTiers": {
          "type": "array",
          "items": {
            "type": "object", "required": ["id", "replenish"],
            "properties": {
              "id": { "$ref": "common.schema.json#/$defs/id" },
              "weapons": { "type": "array", "items": { "$ref": "common.schema.json#/$defs/id" } },
              "replenish": { "oneOf": [{ "const": false }, { "const": "supply_window" }] },
              "sharedBy": { "enum": ["line_a", "line_b"] },
              "hasFloor": { "type": "boolean" }
            },
            "additionalProperties": false
          }
        },
        "historicalEvents": {
          "type": "array",
          "items": {
            "type": "object", "required": ["id", "effect"],
            "properties": {
              "id": { "$ref": "common.schema.json#/$defs/id" },
              "from": { "$ref": "common.schema.json#/$defs/yearMonth" },
              "until": { "$ref": "common.schema.json#/$defs/yearMonth" },
              "effect": { "enum": ["unit_unavailable", "resupply_mult"] },
              "unit": { "$ref": "common.schema.json#/$defs/id" },
              "weapon": { "$ref": "common.schema.json#/$defs/id" },
              "mult": { "$ref": "#/$defs/mult" }
            },
            "additionalProperties": false
          }
        },
        "commandPointsPerNight": { "$ref": "common.schema.json#/$defs/minMax" },
        "trust": { "type": "object" },
        "crossLevelModClamp": { "type": "object" },
        "cityResource": { "type": "object" },
        "supply": { "type": "object" },
        "repair": { "type": "object" },
        "relocation": { "type": "object" },
        "emergencySupport": { "type": "object" },
        "requests": { "type": "array", "items": { "type": "object" } }
      },
      "additionalProperties": false
    },

    "movement": {
      "type": "object",
      "required": ["altitudeBandsM", "cruiseDescentAngleDeg", "highDiveAngleDeg", "ballisticTerminalAngleDeg", "quasiBallisticTerminalAngleDeg", "diveSpeedMult"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "altitudeBandsM": { "type": "object", "additionalProperties": { "$ref": "common.schema.json#/$defs/minMax" } },
        "cruiseDescentAngleDeg": { "type": "number", "exclusiveMinimum": 0 },
        "highDiveAngleDeg": { "type": "number", "exclusiveMinimum": 0 },
        "ballisticTerminalAngleDeg": { "type": "number", "exclusiveMinimum": 0 },
        "quasiBallisticTerminalAngleDeg": { "type": "number", "exclusiveMinimum": 0 },
        "diveSpeedMult": { "$ref": "#/$defs/mult" }
      },
      "additionalProperties": false
    },

    "terrain": {
      "type": "object",
      "required": ["losSampleStepPx", "earthRadiusM", "refractionK", "defaultAntennaHeightM", "horizonAzimuthBins"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "losSampleStepPx": { "type": "number", "exclusiveMinimum": 0 },
        "earthRadiusM": { "type": "number", "exclusiveMinimum": 0 },
        "refractionK": { "type": "number", "exclusiveMinimum": 0 },
        "defaultAntennaHeightM": { "type": "number", "minimum": 0 },
        "horizonAzimuthBins": { "type": "integer", "minimum": 1 }
      },
      "additionalProperties": false
    },

    "engagement": {
      "type": "object",
      "required": ["byWeaponKind", "reactionGameSecByClass", "barrelCooldown", "defaultLaunchers", "maxSalvoSize", "allocation", "defaultRule", "defaultRuleByTag", "fighterRule"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "byWeaponKind": { "type": "object" },
        "reactionGameSecByClass": { "type": "object", "additionalProperties": { "type": "number", "minimum": 0 } },
        "barrelCooldown": { "type": "object" },
        "defaultLaunchers": { "type": "integer", "minimum": 1 },
        "maxSalvoSize": { "type": "integer", "minimum": 1 },
        "allocation": { "type": "string" },
        "defaultRule": { "type": "object" },
        "defaultRuleByTag": { "type": "object" },
        "fighterRule": { "type": "object" }
      },
      "additionalProperties": false
    },

    "civil": {
      "type": "object",
      "required": ["grid", "alert", "scoring"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "grid": { "type": "object" },
        "alert": { "type": "object" },
        "scoring": { "type": "object" }
      },
      "additionalProperties": false
    },

    "enemy_ai": {
      "type": "object",
      "required": ["knownTargets", "exposure100", "probe", "suppress", "saturate", "bypass"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "knownTargets": { "type": "object" },
        "exposure100": { "type": "object" },
        "probe": { "type": "object" },
        "suppress": { "type": "object" },
        "saturate": { "type": "object" },
        "bypass": { "type": "object" }
      },
      "additionalProperties": false
    },

    "commands": {
      "type": "object",
      "required": ["commandPointCosts", "moveUnitTiers", "relocateUnitTiers", "armChoice", "maxOpenAutoChoices", "storyChoice"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "commandPointCosts": { "type": "object", "additionalProperties": { "type": "integer", "minimum": 0 } },
        "moveUnitTiers": { "type": "array", "items": { "type": "string" } },
        "relocateUnitTiers": { "type": "array", "items": { "type": "string" } },
        "armChoice": { "type": "object" },
        "maxOpenAutoChoices": { "type": "integer", "minimum": 1 },
        "storyChoice": { "type": "object" }
      },
      "additionalProperties": false
    },

    "campaign_rules": {
      "type": "object",
      "required": ["crew", "alert", "autoResolve", "adaptation", "dossier", "cityMemory", "rewardCards", "balanceTargets"],
      "properties": {
        "$schema": true, "kind": true, "_source": { "$ref": "common.schema.json#/$defs/source" }, "provisional": { "$ref": "common.schema.json#/$defs/provisional" },
        "crew": { "type": "object" },
        "alert": { "type": "object" },
        "autoResolve": { "type": "object" },
        "adaptation": { "type": "object" },
        "dossier": { "type": "object" },
        "cityMemory": { "type": "object" },
        "rewardCards": { "type": "object" },
        "balanceTargets": { "type": "object" }
      },
      "additionalProperties": false
    }
  }
}

data/schema/sensor.schema.json.content:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "sensor.schema.json",
  "title": "探测单位（数值表 1.3）",
  "type": "object",
  "required": ["sensors"],
  "properties": {
    "$schema": { "type": "string" },
    "sensors": { "type": "array", "items": { "$ref": "#/$defs/sensor" } }
  },
  "additionalProperties": false,
  "$defs": {
    "sensor": {
      "type": "object",
      "required": ["id", "nameKey", "layer", "detectionRangeKm", "lowAltitude", "trackQuality", "emission", "exposureLevel", "deployGameSec", "packGameSec", "priceMusd"],
      "properties": {
        "id": { "$ref": "common.schema.json#/$defs/id" },
        "nameKey": { "$ref": "common.schema.json#/$defs/locKey" },
        "layer": { "enum": ["national", "regional", "local"], "description": "国家层（地图外）/ 区域层 / 本地层" },
        "detectionRangeKm": {
          "type": ["number", "null"], "minimum": 0,
          "description": "探测距离（游戏 km）；null = 覆盖由 coverage 决定"
        },
        "coverage": { "enum": ["full_map", "urban_areas"], "description": "特殊覆盖方式：全图 / 城区全覆盖" },
        "lowAltitude": {
          "enum": ["poor", "medium", "good", "very_good"],
          "description": "低空能力：差 / 中 / 好 / 很好。数值化由 WS01-007 决定"
        },
        "largeLowAltitudeBlindZone": { "type": "boolean", "description": "数值表注明\"低空盲区大\"" },
        "trackQuality": { "enum": ["vague", "approximate"], "description": "探测单位输出航迹质量封顶为大致（B-T2-33）" },
        "trackQualityUpgrades": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["to", "condition"],
            "properties": {
              "to": { "enum": ["approximate"] },
              "condition": { "enum": ["close_range", "linked_drone_types"] },
              "enemies": { "type": "array", "items": { "$ref": "common.schema.json#/$defs/id" } }
            },
            "additionalProperties": false
          },
          "description": "特定条件下航迹质量提升"
        },
        "fastUpdate": { "type": "boolean", "description": "更新快、误差圈小" },
        "onlyDetects": { "enum": ["radio_linked_drones"], "description": "只能探测某类目标" },
        "falseAlarms": { "enum": ["some", "high"], "description": "有误报 / 误报率高" },
        "reportDelay": { "type": "boolean", "description": "上报有延迟" },
        "nightRangeMult": { "type": "number", "minimum": 0, "description": "夜间探测距离倍率" },
        "nightPenaltyNegatedBy": {
          "type": "array", "items": { "enum": ["searchlight", "thermal"] },
          "description": "可抵消夜间惩罚的装备"
        },
        "emission": { "enum": ["active", "passive", "none"], "description": "辐射：主动 / 被动 / 无" },
        "exposureLevel": {
          "enum": ["high", "medium", "zero", "none"],
          "description": "暴露速度：高 / 中 / 0 / 不适用。每秒数值见 rules/exposure.json"
        },
        "lineOfSight": { "type": ["boolean", "null"], "description": "是否受地形视线遮挡（缺省 true，声学哨为 false）" },
        "antennaHeightM": { "type": ["number", "null"], "minimum": 0, "description": "天线高度（米 AGL，缺省取 terrain.defaultAntennaHeightM）" },
        "deployGameSec": { "type": ["number", "null"], "minimum": 0 },
        "packGameSec": { "type": ["number", "null"], "minimum": 0 },
        "priceMusd": { "type": ["number", "null"], "minimum": 0, "description": "null = 库存或不可购买" },
        "stockOnly": { "type": "boolean" },
        "automatic": { "type": "boolean", "description": "自动生效，不需要部署" },
        "firstAvailable": { "$ref": "common.schema.json#/$defs/firstAvailable" },
        "_source": { "$ref": "common.schema.json#/$defs/source" },
        "provisional": { "$ref": "common.schema.json#/$defs/provisional" }
      },
      "additionalProperties": false
    }
  }
}

data/schema/support.schema.json.content:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "support.schema.json",
  "title": "呼叫型外部支援（数值表 1.6）",
  "type": "object",
  "required": ["support"],
  "properties": {
    "$schema": { "type": "string" },
    "support": { "type": "array", "items": { "$ref": "#/$defs/support" } }
  },
  "additionalProperties": false,
  "$defs": {
    "support": {
      "type": "object",
      "required": ["id", "nameKey", "provider", "effect", "delay", "cost"],
      "properties": {
        "id": { "$ref": "common.schema.json#/$defs/id" },
        "nameKey": { "$ref": "common.schema.json#/$defs/locKey" },
        "provider": { "enum": ["air_force", "higher_ew", "neighbor_oblast", "regional_ad_command"] },
        "effect": {
          "enum": ["area_patrol", "directed_intercept", "uav_hunt", "accuracy_drop", "reinforcement", "sector_coverage"]
        },
        "fighterRef": { "$ref": "common.schema.json#/$defs/id", "description": "引用 support/fighters.json" },
        "fighterWeaponRef": { "$ref": "common.schema.json#/$defs/id", "description": "使用的机载武器 ID" },
        "targets": {
          "type": "array", "uniqueItems": true,
          "items": { "$ref": "common.schema.json#/$defs/targetTag" }
        },
        "killsPerSortie": { "type": "integer", "minimum": 1 },
        "accuracyTierDrop": { "type": "integer", "minimum": 1 },
        "radiusKm": { "$ref": "common.schema.json#/$defs/positive" },
        "affectsSameAsEwUnit": { "$ref": "common.schema.json#/$defs/id", "description": "影响对象与该电子战单位相同（引用 units/ew.json）" },
        "reinforcementUnit": { "$ref": "common.schema.json#/$defs/id", "description": "引用 units/air_defense.json" },
        "reinforcementCount": { "type": "integer", "minimum": 1 },
        "coverageUnits": {
          "type": "array", "items": { "$ref": "common.schema.json#/$defs/id" },
          "description": "提供覆盖的系统（引用 units/air_defense.json）"
        },
        "delay": {
          "type": "object",
          "required": ["kind"],
          "properties": {
            "kind": { "enum": ["game_sec", "next_day", "instant"] },
            "offMapGameSec": { "$ref": "common.schema.json#/$defs/nonNegative" },
            "onMapAirbaseGameSec": { "$ref": "common.schema.json#/$defs/nonNegative" },
            "gameSec": { "$ref": "common.schema.json#/$defs/nonNegative" }
          },
          "additionalProperties": false
        },
        "duration": {
          "type": "object",
          "required": ["kind"],
          "properties": {
            "kind": { "enum": ["game_sec", "until_ammo_out", "nights", "same_as_ew_unit"] },
            "gameSec": { "$ref": "common.schema.json#/$defs/positive" },
            "nights": { "type": "integer", "minimum": 1 }
          },
          "additionalProperties": false
        },
        "cost": {
          "type": "object",
          "properties": {
            "commandPoints": { "type": "integer", "minimum": 0 },
            "trust": { "enum": ["small", "large"], "description": "信任度代价：一般 / 大" }
          },
          "additionalProperties": false,
          "minProperties": 1
        },
        "firstAvailable": { "$ref": "common.schema.json#/$defs/firstAvailable" },
        "_source": { "$ref": "common.schema.json#/$defs/source" },
        "provisional": { "$ref": "common.schema.json#/$defs/provisional" }
      },
      "additionalProperties": false
    }
  }
}

data/schema/waves.schema.json.content:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "waves.schema.json",
  "title": "波次 waves.json（WBS 02.A）",
  "type": "object",
  "required": ["$schema", "entryPoints", "nights"],
  "properties": {
    "$schema": { "type": "string" },
    "entryPoints": {
      "type": "array", "minItems": 1,
      "items": {
        "type": "object", "required": ["id", "positionM"],
        "properties": {
          "id": { "$ref": "common.schema.json#/$defs/id" },
          "nameKey": { "$ref": "common.schema.json#/$defs/locKey" },
          "positionM": { "$ref": "common.schema.json#/$defs/pointM", "description": "进入点（可在地图边缘或地图外）" },
          "warningGameSec": { "type": "number", "minimum": 0, "description": "国家预警网提前多少游戏秒给出\"模糊\"预警" }
        },
        "additionalProperties": false
      }
    },
    "nights": {
      "type": "array", "minItems": 1,
      "items": {
        "type": "object", "required": ["night", "durationGameSec", "waves"],
        "properties": {
          "night": { "type": "integer", "minimum": 0, "description": "夜晚序号（>=1）；0 = auto_night 自动结算夜晚模板（05_campaign_economy.md §1.4）" },
          "date": { "$ref": "common.schema.json#/$defs/date" },
          "timeOfDay": { "enum": ["night", "day"] },
          "isBigRaid": { "type": "boolean" },
          "allowSupport": { "type": "boolean" },
          "commandPoints": { "type": "integer", "minimum": 0 },
          "durationGameSec": { "type": "number", "exclusiveMinimum": 0, "description": "一夜的长度（游戏秒）；GDD 11.2：一夜约 6–10 分钟" },
          "weather": { "enum": ["clear", "moonlit", "low_cloud", "fog"], "description": "GDD 8.8" },
          "season": { "enum": ["spring", "summer", "autumn", "winter"] },
          "waves": {
            "type": "array",
            "items": {
              "type": "object", "required": ["id", "atGameSec", "groups"],
              "properties": {
                "id": { "$ref": "common.schema.json#/$defs/id" },
                "atGameSec": { "type": "number", "minimum": 0, "description": "本波开始时刻（相对夜晚开始）" },
                "aiTags": {
                  "type": "array", "uniqueItems": true,
                  "items": { "enum": ["probe", "suppress", "hunt", "bypass", "saturate"] },
                  "description": "GDD 7.4：试探 / 压制 / 猎杀 / 绕行 / 饱和"
                },
                "groups": {
                  "type": "array", "minItems": 1,
                  "items": {
                    "type": "object", "required": ["enemy", "count", "entry", "route", "target"],
                    "properties": {
                      "enemy": { "$ref": "common.schema.json#/$defs/id", "description": "引用 enemies/*.json 的 ID" },
                      "count": { "type": "integer", "minimum": 1 },
                      "entry": { "$ref": "common.schema.json#/$defs/id", "description": "引用 entryPoints" },
                      "spacingGameSec": { "type": "number", "minimum": 0, "description": "同组目标之间的间隔" },
                      "route": {
                        "oneOf": [
                          {
                            "type": "object", "required": ["template"],
                            "properties": { "template": { "$ref": "common.schema.json#/$defs/id", "description": "航线模板（WS02-004）" } },
                            "additionalProperties": false
                          },
                          {
                            "type": "object", "required": ["waypointsM"],
                            "properties": {
                              "waypointsM": {
                                "type": "array", "minItems": 1,
                                "items": { "$ref": "common.schema.json#/$defs/pointM" },
                                "description": "进入点与目标之间的中间航点"
                              }
                            },
